-- Target PostgreSQL schema for numeric IDs and user-owned conversations.
-- Run against an empty database or after separately removing the old tables.
-- This is a creation script, not a migration for existing data.
-- The C# entities and CosmoDbContext must be updated to match before use.
-- IDs are generated by PostgreSQL; zero-based sequence numbers are assigned by the app.
-- Role values: 0 = System, 1 = User, 2 = Assistant.

BEGIN;

CREATE TABLE "Users" (
    "Id" integer GENERATED ALWAYS AS IDENTITY,
    "ExternalIssuer" text NOT NULL,
    "ExternalSubject" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_Users_ExternalIssuer_ExternalSubject"
        UNIQUE ("ExternalIssuer", "ExternalSubject")
);

CREATE TABLE "Conversations" (
    "Id" integer GENERATED ALWAYS AS IDENTITY,
    "UserId" integer NOT NULL,
    "Title" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_Conversations" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Conversations_Users_UserId"
        FOREIGN KEY ("UserId") REFERENCES "Users" ("Id")
        ON DELETE RESTRICT
);

CREATE INDEX "IX_Conversations_UserId"
    ON "Conversations" ("UserId");

CREATE TABLE "ConversationMessages" (
    "Id" integer GENERATED ALWAYS AS IDENTITY,
    "SequenceNumber" integer NOT NULL,
    "Role" integer NOT NULL,
    "Content" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ConversationId" integer NOT NULL,
    CONSTRAINT "PK_ConversationMessages" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ConversationMessages_Conversations_ConversationId"
        FOREIGN KEY ("ConversationId") REFERENCES "Conversations" ("Id")
        ON DELETE CASCADE
);

CREATE UNIQUE INDEX "IX_ConversationMessages_ConversationId_SequenceNumber"
    ON "ConversationMessages" ("ConversationId", "SequenceNumber");

COMMIT;
